         /*
 CSS for the main interaction
*/
.tabset > input[type="radio"] {
  position: absolute;
  left: -200vw;
}

.tabset .tab-panel {
  display: none;
}

.tabset > input:first-child:checked ~ .tab-panels > .tab-panel:first-child,
.tabset > input:nth-child(3):checked ~ .tab-panels > .tab-panel:nth-child(2),
.tabset > input:nth-child(5):checked ~ .tab-panels > .tab-panel:nth-child(3),
.tabset > input:nth-child(7):checked ~ .tab-panels > .tab-panel:nth-child(4),
.tabset > input:nth-child(9):checked ~ .tab-panels > .tab-panel:nth-child(5),
.tabset > input:nth-child(11):checked ~ .tab-panels > .tab-panel:nth-child(6) {
  display: block;
}

/*
 Styling
*/

.tabset > label {
  position: relative;
  display: inline-block;
  padding: 15px 15px 25px;

  border-bottom: 0;
  cursor: pointer;
  font-weight: 600;
  background-color: transparent;
border-bottom: 2px solid transparent;
padding: 1px;
margin-right: 50px;
font-weight: 600;
font-size: 20px;
line-height: 1.2;
position: relative;
color: #232323;
}
label svg {
  height: 45px;
  left: 0;
  position: absolute;
  top: 0;
  border-radius: 2px;
  width: 100%;
}
svg:not(:root) {
  overflow: hidden;
}
.tabset > label:active::after {
  background-color: var(--ltn__secondary-color);
  border: 3px solid var(--white);
  color: #d84c0d;
}
.tabset > label::after {
  position: absolute;
content: "";
right: 45%;
top: 100%;
-webkit-transform: translateY(-40%);
-ms-transform: translateY(-40%);
transform: translateY(-40%);
height: 10px;
width: 10px;
background-color: transparent;
opacity: 1;
border: 3px solid transparent;
border-radius: 100%;
}
/* .tabset > label:active {
  color: var(--ltn__secondary-color);
} */

.tabset > label:hover, .tabset > input:active + label,
.tabset > input:focus + label {
    color:#d84c0d !important;;
    background-color: transparent;
    border-color: var(--ltn__secondary-color);
}

/* .tabset label:active {
  color: var(--ltn__secondary-color);
  background-color: transparent;
  border-color: var(--ltn__secondary-color);
} */

/* .tabset > label:hover::after,
.tabset > input:focus,
.tabset > input:checked,.tabset > input:active  {
  background: #ff5a3c;
} */

.tabset > input:checked + label {
  border-color: #ccc;
  border-bottom: 1px solid #fff;
  margin-bottom: -1px;
  border: none;
}

.tab-panel {
  padding: 30px 0;
  border-top: 1px solid #ccc;
  border: none;
}
.gt-event-style-3 .gt-category ul li {
  background-color: #ececec;
}
.gt-event-style-3 .gt-details + .gt-text {
  margin-top: 20px;
  text-align: left;
}
.gt-content{
  border-top-color: #f6ba42 !important;
}
.gt-all-button {
  color: #d84c0d;
  font-size: 1.25em;
}
.gt-all-button:hover, .gt-all-button:focus  {
  color: #d84c0d !important;
  font-size: 1.25em;
  text-decoration: underline;
}
.rs-about.style1 .notice-bord.style1 .title {
 background: none;
font-size: 22px;
text-transform: uppercase;
padding: 0 5px;
text-align: left;
font-weight: 600;
color: #e22023;
margin-bottom: 10px;
}
